1	/**
2	 * Позиции счёта.
3	 *
4	 * Позиция — то, за что платят: название, количество, цена единицы. Скидок и налогов здесь
5	 * нет намеренно: они применяются к счёту целиком на сборке, а не к строкам — иначе итог
6	 * перестаёт сходиться с подытогом на округлениях каждой строки.
7	 */
8	
9	import type { Kopeck } from './money.ts';
10	
11	export interface Line {
12	  title: string;
13	  /** Количество, целое. Дробного количества у нас нет — штучный товар. */
14	  qty: number;
15	  /** Цена единицы в копейках. */
16	  priceK: Kopeck;
17	}
18	
19	/** Стоимость позиции: количество × цена единицы. */
20	export function lineTotal(line: Line): Kopeck {
21	  return line.qty * line.priceK;
22	}
23	
24	/** Подытог счёта — сумма по позициям, до всяких налогов. */
25	export function subtotal(lines: readonly Line[]): Kopeck {
26	  let sum = 0;
27	  for (const line of lines) sum += lineTotal(line);
28	  return sum;
29	}
30

1	/**
2	 * Конфигурация биллинга.
3	 *
4	 * Всё, что меняется между площадками, живёт здесь, а не размазано по коду. Читается через
5	 * resolveConfig: прямое обращение к DEFAULT_CONFIG из модулей запрещено — иначе переопределение
6	 * конфига молча перестаёт действовать на половину мест.
7	 */
8	
9	export interface BillingConfig {
10	  /** Валюта счетов. Других у нас нет, но поле есть: отчётность её читает. */
11	  currency: 'RUB';
12	}
13	
14	export const DEFAULT_CONFIG: BillingConfig = {
15	  currency: 'RUB',
16	};
17	
18	/** Конфиг с переопределениями площадки. Не указанное — из DEFAULT_CONFIG. */
19	export function resolveConfig(partial?: Partial<BillingConfig>): BillingConfig {
20	  return { ...DEFAULT_CONFIG, ...partial };
21	}
22

